```tsx
import "./ChecklistItem.css";

export interface ChecklistItemProps {
  title: string;
  detail: string;
  minutes: number;
  done: boolean;
  onToggle: () => void;
}

export function ChecklistItem({
  title,
  detail,
  minutes,
  done,
  onToggle,
}: ChecklistItemProps) {
  return (
    <div className={done ? "checklist-item checklist-item--done" : "checklist-item"}>
      <button
        type="button"
        className="checklist-item__check"
        aria-pressed={done}
        aria-label={title}
        onClick={onToggle}
      >
        {done && (
          <svg
            className="checklist-item__tick"
            viewBox="0 0 16 16"
            aria-hidden="true"
            focusable="false"
          >
            <path d="M3.5 8.5 6.5 11.5 12.5 4.5" />
          </svg>
        )}
      </button>

      <div className="checklist-item__text">
        <span className="checklist-item__title">{title}</span>
        <span className="checklist-item__detail">{detail}</span>
      </div>

      <span className="checklist-item__duration">{minutes} min</span>
    </div>
  );
}
```

```css
.checklist-item {
  display: flex;
  align-items: center;
  gap: clamp(0.75rem, 1.5vw, 1rem);
  padding: clamp(0.6rem, 1.2vw, 0.9rem) 0;
  border-bottom: 1px solid var(--hair);
  color: var(--ink);
  font: inherit;
}

.checklist-item__check {
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  width: clamp(1.5rem, 2.4vw, 1.8rem);
  height: clamp(1.5rem, 2.4vw, 1.8rem);
  padding: 0;
  border-radius: 50%;
  border: 2px solid var(--ink);
  background: transparent;
  color: var(--slide);
  cursor: pointer;
  font: inherit;
}

.checklist-item__check[aria-pressed="true"] {
  background: var(--myelin);
  border-color: var(--myelin);
}

.checklist-item__tick {
  width: 62%;
  height: 62%;
  fill: none;
  stroke: currentColor;
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.checklist-item__text {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
}

.checklist-item__title {
  font: inherit;
  font-size: clamp(0.95rem, 1.6vw, 1.1rem);
  color: var(--ink);
  transition: color 200ms ease;
}

.checklist-item__detail {
  font: inherit;
  font-size: clamp(0.8rem, 1.3vw, 0.9rem);
  color: var(--muted);
}

.checklist-item__duration {
  flex: 0 0 auto;
  font: inherit;
  font-size: clamp(0.8rem, 1.3vw, 0.9rem);
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.checklist-item--done .checklist-item__title {
  color: var(--muted);
}

.checklist-item--done .checklist-item__detail {
  color: var(--muted);
}

:root[data-motion="reduce"] .checklist-item__title,
:root[data-motion="reduce"] .checklist-item__check {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .checklist-item__title,
  .checklist-item__check {
    transition: none;
  }
}
```

